// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address payable owner;

    function setUp() public {
        // make the owner an EOA so ETH transfers out of c always succeed
        owner = payable(vm.addr(0xBEEF));
        vm.startPrank(owner);
        c = new C();
        vm.stopPrank();
    }

    function testFuzz_property(uint256 amount, address depositor) public {
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(c));
        vm.assume(depositor != owner);
        amount = bound(amount, 2, 1 ether);

        // depositor funds c through the payable fallback
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool okDep, ) = address(c).call{value: amount}("");
        require(okDep, "deposit failed");

        uint256 balBefore = address(c).balance;
        uint256 ownerBefore = owner.balance;

        // owner withdraws everything
        vm.prank(owner);
        c.withdrawAll();

        assertTrue(
            address(c).balance == 0 && owner.balance == ownerBefore + balBefore,
            "withdrawAll must drain the entire balance to the owner"
        );
    }
}

