pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address funder) public {
        vm.assume(funder != address(c) && funder != address(this));
        amount = bound(amount, 3, 1 ether);

        // fund the contract via its payable fallback with a fuzzed amount from a fuzzed funder
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool deposited, ) = address(c).call{value: amount}("");
        vm.assume(deposited);

        // owner drains the contract
        vm.prank(address(this));
        try c.withdrawAll() { /* drained in P */ } catch { /* shouldn't happen for owner */ }

        // RULE: once withdrawAll has run, the contract holds nothing, so ANY further
        // payout attempt (here 2 wei) must revert.
        bool paidOut;
        vm.prank(address(this));
        try c.withdraw(2) {
            paidOut = true;
        } catch {
            paidOut = false;
        }
        assertTrue(!paidOut, "withdrawAll must leave the contract empty");
    }
}

