contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test() public {
        // msg.sender here is this test contract, which is not the owner of c.
        // On P, sendMoney is guarded by onlyOwner and reverts for a non-owner;
        // on M, the guard is removed and the call succeeds.
        bool sent = false;
        try c.sendMoney(address(this), 0) {
            sent = true;
        } catch {
            sent = false;
        }
        assert(!sent);
    }

    receive() external payable {}
    fallback() external payable {}
}

